import { Component, ElementRef, HostListener, Input, ViewChild } from '@angular/core';
import { CommonModule } from "@angular/common";
import { FormsModule } from "@angular/forms";
import { VanillaDialogService } from '../../services/vanilla-dialog/vanilla-dialog.service';

@Component({
    selector: 'app-vanilla-dialog',
    imports: [
        CommonModule,
        FormsModule,
    ],
    templateUrl: './vanilla-dialog.component.html',
    styleUrl: './vanilla-dialog.component.css'
})
export class VanillaDialogComponent {
  @Input()
  tipo: string | undefined = "";
  @Input()
  show: boolean = false
  hide:boolean=false
  @Input()
  title: string | undefined;
  @Input()
  body: string | undefined;
  @Input()
  respYes: string | undefined = 'Aceptar';
  @Input()
  respNot: string | undefined;
  @Input()
  size: string | undefined = "m";

  @ViewChild('dialogoElement')
  dialogoElement!: ElementRef;

  //Este es solo el template

  /* queda pendiente no lo hice hacer funcionar. Es para cerrar si se hace click fuera del div
  @HostListener('document:click', ['$event'])
  clickOutside(event: Event) {
    // Comprobar si el clic ocurrió fuera del área del diálogo
    if (!this.dialogoElement.nativeElement.contains(event.target)) {
      // Lógica para cerrar el diálogo
      const data={
        closedByOutside:true,
      }
      this.dialogService.close(data)
    }
  }*/

  constructor(private dialogService: VanillaDialogService) {
  }

  ngOnChanges(){
    if(this.show){
      //si esta oculto lo muestra de inmediato
      if(this.hide){
        this.hide=false
      }
      //si no esta oculto es decir la venta ya esta abierta, espera que la ventana se termine de abrir o cerrar para mostrarla
      setTimeout(()=>{
        if(this.show){
          this.hide=false
        }
      },500)
    }else{
      //si esta abierto lo activa la animacion para cerrarlo
      if(!this.hide){
        setTimeout(()=>{
          if(!this.show){
            this.hide=true
          }
        },500)
      }else{
        //esta en proceso de abrirse, damos tiempo que termine la animacion antes de cerrarlo
        setTimeout(()=>{
          setTimeout(()=>{
            if(!this.show){
              this.hide=true
            }
          },500)
        },500)
      }
    }
  }

  getSize(): string {
    switch (this.size) {
      case 's':
        return 'col-lg-3 p-4'
      case 'm':
        return 'col-lg-5 p-4'
      case 'l':
        return 'col-lg-7 p-4'
      case 'xl':
        return 'col-lg-9 p-3'
      default:
        return 'col-lg-5 p-4'
    }
  }
  animationClass() {
    if (this.show) {
      return 'fade-in'
    } else {
      return 'fade-out'
    }
  }

  icon_class(): string {
    let tipo = ''
    switch (this.tipo) {
      case "success":
        tipo = 'bi-check-circle text-success'
        break
      case "warning":
        tipo = 'bi-exclamation-circle text-warning'
        break
      case "danger":
        tipo = 'bi-x-circle text-danger'
        break
      case "info":
        tipo = 'bi-info-square text-info'
        break
      case "confirm":
        tipo = 'bi bi-question-circle text-secondary'
        break;
      default:
        tipo = 'bi-exclamation-triangle text-primary '
    }
    return tipo;
  }

  tipoTitle(): string {
    let tipo = ''
    switch (this.tipo) {
      case "success":
        tipo = 'text-success'
        break
      case "warning":
        tipo = 'text-warning'
        break
      case "danger":
        tipo = 'text-danger'
        break
      case "info":
        tipo = 'text-info'
        break
      case "confirm":
        tipo = 'text-secondary'
        break;
      default:
        tipo = 'text-primary'
    }
    return tipo;
  }
  borderColor(): string {
    let tipo = ''
    switch (this.tipo) {
      case "success":
        tipo = 'border-success-subtle'
        break
      case "warning":
        tipo = 'border-warning-subtle'
        break
      case "danger":
        tipo = 'border-danger-subtle'
        break
      case "info":
        tipo = 'border-info-subtle'
        break
      case "confirm":
        tipo = 'border-secondary-subtle'
        break;
      default:
        tipo = 'border-primary-subtle'
    }
    return tipo;
  }

  //se comunica con el servicio para indicarle que se debe cerrar y de que forma fue cerrado
  accion(value: string) {
    let data
    switch (value) {
      case "si":
        data = {
          closedByAgree: true,
        }
        this.dialogService.close(data)
        break
      case "no":
        data = {
          closedByCancelled: true,
        }
        this.dialogService.close(data)
        break
      default:
        this.dialogService.close(undefined)
    }
  }
}
