import { Routes } from '@angular/router';
import { NotFoundComponent } from './info/not-found/not-found.component';
import { authGuard } from './auth/auth.guard';
import { noAuthGuard } from './auth/no-auth.guard';

export const routes: Routes = [
    { 
        path:'',
        canActivate: [noAuthGuard],
        title:'Login',
        loadComponent: ()=> import('./auth/auth.component').then(c => c.AuthComponent),
        loadChildren: () => import('./auth/auth.routes').then(m=> m.authRoutes),
    },
    { 
        path:'main', 
        title:'Fondos BC',
        canActivate:[ authGuard ],
        loadComponent: () => import('./main/main.component').then( c => c.MainComponent), 
        loadChildren: ()=> import('./main/main.routes').then(m => m.mainRoutes ) 
    },
    { 
        path:'configuracion', 
        title:'Configuración',
        canActivate:[ authGuard ],
        loadComponent: () => import('./configuracion/configuracion.component').then( c => c.ConfiguracionComponent), 
        loadChildren: () => import('./configuracion/configuracion.routes').then(m => m.configRoutes),
    },
    {
        path:'pagos',
        title:'Pagos',
        canActivate:[ authGuard ],
        loadComponent: () => import('./pagos/pagos.component').then(c => c.PagosComponent),
        loadChildren: () => import('./pagos/pagos.routes').then(m => m.pagosRoutes)
    },
    { 
        path:'catalogos',
        title:'Catalogos',
        canActivate:[ authGuard ],
        loadComponent: () => import('./catalogos/catalogos.component').then(c=> c.CatalogosComponent), 
        loadChildren: () => import('./catalogos/catalogos.routes').then(m => m.catalogosRoutes),
    },
    {
        path:'clientes',
        title:'Acreditados',
        loadChildren: () => import('./clientes/clientes.routes').then(m => m.clientesRoutes),
    },
    { path:'**', loadComponent: () => import('./info/not-found/not-found.component').then(m => m.NotFoundComponent) },
];
