import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { UsuarioLogin } from './auth.model';

export const authGuard: CanActivateFn = (route, state) => {
  const userLogin= localStorage.getItem('user') as UsuarioLogin|null
  const router = inject(Router); // Usa inject para obtener el Router en un Guard de tipo function
  if (!userLogin || (userLogin.update_token && (Date.now() - new Date(userLogin.update_token).getTime()) > 60 * 60 * 1000)) {
    localStorage.removeItem('user');
    router.navigate(['/login']);
  }
  return !!userLogin;
};